package com.familygrowth.infrastructure;
import static com.familygrowth.domain.Stage31EconomyModels.*;import com.familygrowth.application.*;import java.math.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.sql.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository class JdbcStage31EconomyStore implements Stage31EconomyStore{
 private final JdbcTemplate jdbc;JdbcStage31EconomyStore(JdbcTemplate j){jdbc=j;}
 @Override public SavingRewardRule configureSaving(UUID f,BigDecimal rate,BigDecimal minimum,UUID actor,Instant now){if(rate.signum()<0||rate.compareTo(new BigDecimal("0.100000"))>0||minimum.signum()<0)throw new IllegalArgumentException("Invalid saving reward rule");Long version=jdbc.queryForObject("SELECT COALESCE(MAX(rule_version),0)+1 FROM saving_reward_rule WHERE family_id=?",Long.class,f);jdbc.update("UPDATE saving_reward_rule SET active=FALSE WHERE family_id=? AND active=TRUE",f);UUID id=UUID.randomUUID();jdbc.update("INSERT INTO saving_reward_rule(id,family_id,rule_version,periodic_rate,minimum_balance,active,actor_id,created_at) VALUES(?,?,?,?,?,TRUE,?,?)",id,f,version,rate,minimum,actor,ts(now));audit(f,actor,"SAVING_RULE",id,"version="+version,now);return savingRule(f);}
 @Override public SavingRewardAward settleSaving(UUID f,UUID c,String cycle,String key,UUID actor,Instant now){child(f,c);var replay=jdbc.query("SELECT * FROM saving_reward_award WHERE family_id=? AND idempotency_key=?",this::awardRow,f,key).stream().findFirst();if(replay.isPresent()){if(!replay.get().childId().equals(c)||!replay.get().cycleKey().equals(cycle))throw new Stage3Service.ConflictException("Idempotency-Key payload mismatch");return replay.get();}SavingRewardRule rule=savingRule(f);jdbc.update("INSERT INTO saving_account(child_id,family_id,balance,version,created_at,updated_at) SELECT ?,?,0.00,0,?,? WHERE NOT EXISTS(SELECT 1 FROM saving_account WHERE family_id=? AND child_id=?)",c,f,ts(now),ts(now),f,c);BigDecimal saving=jdbc.queryForObject("SELECT balance FROM saving_account WHERE family_id=? AND child_id=? FOR UPDATE",BigDecimal.class,f,c);if(saving.compareTo(rule.minimumBalance())<0)throw new Stage3Service.ConflictException("Saving balance is below the configured minimum");BigDecimal reward=saving.multiply(rule.periodicRate()).setScale(2,RoundingMode.HALF_UP);if(reward.signum()<=0)throw new Stage3Service.ConflictException("Configured reward rounds to zero");BigDecimal wallet=jdbc.queryForObject("SELECT money_balance FROM wallet WHERE family_id=? AND child_id=? FOR UPDATE",BigDecimal.class,f,c),credited=wallet.add(reward),savingAfter=saving.add(reward);UUID id=UUID.randomUUID(),group=UUID.randomUUID();jdbc.update("INSERT INTO saving_reward_award(id,family_id,child_id,rule_id,cycle_key,base_balance,reward_amount,ledger_group_id,idempotency_key,actor_id,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)",id,f,c,rule.id(),cycle,saving,reward,group,key,actor,ts(now));ledger(f,c,reward,wallet,credited,"SAVING_REWARD_CREDIT",id,group,key,actor,"Family saving reward; cycle="+cycle,now);ledger(f,c,reward.negate(),credited,wallet,"SAVING_REWARD_DEPOSIT",id,group,key,actor,"Saving reward moved into internal saving",now);jdbc.update("UPDATE saving_account SET balance=?,version=version+1,updated_at=? WHERE family_id=? AND child_id=?",savingAfter,ts(now),f,c);audit(f,actor,"SAVING_AWARD",id,"cycle="+cycle+";reward="+reward,now);return award(f,id);}
 @Override public SimulatedMarketRule configureMarket(UUID f,UUID fund,String seed,int bps,UUID actor,Instant now){fund(f,fund);Long v=jdbc.queryForObject("SELECT COALESCE(MAX(rule_version),0)+1 FROM simulated_market_rule WHERE fund_id=?",Long.class,fund);jdbc.update("UPDATE simulated_market_rule SET active=FALSE WHERE fund_id=? AND active=TRUE",fund);UUID id=UUID.randomUUID();jdbc.update("INSERT INTO simulated_market_rule(id,family_id,fund_id,rule_version,deterministic_seed,maximum_daily_bps,active,actor_id,created_at) VALUES(?,?,?,?,?,?,TRUE,?,?)",id,f,fund,v,seed,bps,actor,ts(now));audit(f,actor,"MARKET_RULE",id,"version="+v+";maxBps="+bps,now);return marketRule(fund);}
 @Override public SimulatedMarketTick tick(UUID f,UUID fund,LocalDate date,String key,UUID actor,Instant now){var existing=jdbc.query("SELECT * FROM simulated_market_tick WHERE family_id=? AND fund_id=? AND tick_date=?",this::tickRow,f,fund,date).stream().findFirst();if(existing.isPresent())return existing.get();SimulatedMarketRule rule=marketRule(fund);Nav latest=jdbc.query("SELECT id,nav FROM fund_nav WHERE family_id=? AND fund_id=? ORDER BY nav_date DESC,created_at DESC LIMIT 1",(r,n)->new Nav(uuid(r,1),r.getBigDecimal(2)),f,fund).stream().findFirst().orElseThrow(()->new Stage3Service.ConflictException("Fund has no NAV"));int span=rule.maximumDailyBps()*2+1;int raw=Math.floorMod(Arrays.hashCode(digest(rule.seedLabel()+"|"+fund+"|"+date)),span)-rule.maximumDailyBps();BigDecimal after=latest.nav.multiply(BigDecimal.ONE.add(BigDecimal.valueOf(raw,4))).setScale(6,RoundingMode.HALF_UP);if(after.signum()<=0)after=new BigDecimal("0.000001");UUID nav=UUID.randomUUID(),id=UUID.randomUUID();BigDecimal pct=BigDecimal.valueOf(raw,2);jdbc.update("INSERT INTO fund_nav(id,family_id,fund_id,nav_date,nav,change_percent,actor_id,created_at) VALUES(?,?,?,?,?,?,?,?)",nav,f,fund,date,after,pct,actor,ts(now));jdbc.update("INSERT INTO simulated_market_tick(id,family_id,fund_id,rule_id,tick_date,change_bps,nav_before,nav_after,fund_nav_id,idempotency_key,actor_id,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",id,f,fund,rule.id(),date,raw,latest.nav,after,nav,key,actor,ts(now));audit(f,actor,"MARKET_TICK",id,"date="+date+";changeBps="+raw,now);return tickById(id);}
 @Override public HoldingFeeRule configureHolding(UUID f,UUID fund,int days,BigDecimal rate,UUID actor,Instant now){fund(f,fund);if(days<0||days>3650||rate.signum()<0||rate.compareTo(new BigDecimal("0.500000"))>0)throw new IllegalArgumentException("Invalid holding fee rule");Long v=jdbc.queryForObject("SELECT COALESCE(MAX(rule_version),0)+1 FROM fund_holding_fee_rule WHERE fund_id=?",Long.class,fund);jdbc.update("UPDATE fund_holding_fee_rule SET active=FALSE WHERE fund_id=? AND active=TRUE",fund);UUID id=UUID.randomUUID();jdbc.update("INSERT INTO fund_holding_fee_rule(id,family_id,fund_id,rule_version,minimum_holding_days,early_fee_rate,active,actor_id,created_at) VALUES(?,?,?,?,?,?,TRUE,?,?)",id,f,fund,v,days,rate,actor,ts(now));audit(f,actor,"HOLDING_RULE",id,"days="+days+";rate="+rate,now);return holdingRule(fund);}
 @Override public EconomyLabSnapshot snapshot(UUID f){SavingRewardRule saving=jdbc.query("SELECT * FROM saving_reward_rule WHERE family_id=? AND active=TRUE",this::savingRuleRow,f).stream().findFirst().orElse(null);List<SimulatedMarketRule> markets=jdbc.query("SELECT * FROM simulated_market_rule WHERE family_id=? AND active=TRUE ORDER BY created_at",this::marketRow,f);List<HoldingFeeRule> holdings=jdbc.query("SELECT * FROM fund_holding_fee_rule WHERE family_id=? AND active=TRUE ORDER BY created_at",this::holdingRow,f);return new EconomyLabSnapshot(saving,markets,holdings,NOTICE);}
 @Override public UUID createCosmetic(UUID f,String title,long cost,int stock,UUID actor,Instant now){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO reward_product(id,family_id,title,coin_cost,stock_count,active,version,actor_id,created_at,product_kind) VALUES(?,?,?,?,?,TRUE,0,?,?,'COSMETIC')",id,f,title,cost,stock,actor,ts(now));audit(f,actor,"COSMETIC_CREATED",id,"fixedCoinCost="+cost,now);return id;}
 private SavingRewardRule savingRule(UUID f){return jdbc.query("SELECT * FROM saving_reward_rule WHERE family_id=? AND active=TRUE",this::savingRuleRow,f).stream().findFirst().orElseThrow(()->new Stage3Service.ConflictException("Saving reward rule is not configured"));}private SimulatedMarketRule marketRule(UUID fund){return jdbc.query("SELECT * FROM simulated_market_rule WHERE fund_id=? AND active=TRUE",this::marketRow,fund).stream().findFirst().orElseThrow(()->new Stage3Service.ConflictException("Simulated market rule is not configured"));}private HoldingFeeRule holdingRule(UUID fund){return jdbc.query("SELECT * FROM fund_holding_fee_rule WHERE fund_id=? AND active=TRUE",this::holdingRow,fund).stream().findFirst().orElseThrow(()->new Stage3Service.ConflictException("Holding fee rule is not configured"));}
 private void child(UUID f,UUID child){if(jdbc.queryForObject("SELECT COUNT(*) FROM child_profile WHERE family_id=? AND id=?",Integer.class,f,child)!=1)throw new FamilyGrowthService.NotFoundException();}private void fund(UUID f,UUID fund){if(jdbc.queryForObject("SELECT COUNT(*) FROM virtual_fund WHERE family_id=? AND id=?",Integer.class,f,fund)!=1)throw new FamilyGrowthService.NotFoundException();}private SavingRewardAward award(UUID f,UUID id){return jdbc.query("SELECT * FROM saving_reward_award WHERE family_id=? AND id=?",this::awardRow,f,id).stream().findFirst().orElseThrow();}private SimulatedMarketTick tickById(UUID id){return jdbc.query("SELECT * FROM simulated_market_tick WHERE id=?",this::tickRow,id).stream().findFirst().orElseThrow();}
 private void ledger(UUID f,UUID c,BigDecimal delta,BigDecimal before,BigDecimal after,String type,UUID business,UUID group,String key,UUID actor,String reason,Instant now){jdbc.update("INSERT INTO ledger_entry(id,family_id,child_id,asset_type,delta,before_balance,after_balance,entry_type,business_type,business_id,group_id,idempotency_key,actor_id,reason,created_at) VALUES(?,?,?,'MONEY',?,?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),f,c,delta,before,after,type,type,business,group,key,actor,reason,ts(now));}private void audit(UUID f,UUID actor,String type,UUID target,String detail,Instant now){jdbc.update("INSERT INTO economy_lab_action(id,family_id,actor_id,action_type,target_id,detail,created_at) VALUES(?,?,?,?,?,?,?)",UUID.randomUUID(),f,actor,type,target,detail,ts(now));}
 private SavingRewardRule savingRuleRow(ResultSet r,int n)throws SQLException{return new SavingRewardRule(uuid(r,"id"),r.getLong("rule_version"),r.getBigDecimal("periodic_rate"),r.getBigDecimal("minimum_balance"),instant(r,"created_at"));}private SavingRewardAward awardRow(ResultSet r,int n)throws SQLException{return new SavingRewardAward(uuid(r,"id"),uuid(r,"child_id"),r.getString("cycle_key"),r.getBigDecimal("base_balance"),r.getBigDecimal("reward_amount"),uuid(r,"ledger_group_id"),instant(r,"created_at"));}private SimulatedMarketRule marketRow(ResultSet r,int n)throws SQLException{return new SimulatedMarketRule(uuid(r,"id"),uuid(r,"fund_id"),r.getLong("rule_version"),r.getString("deterministic_seed"),r.getInt("maximum_daily_bps"),instant(r,"created_at"));}private SimulatedMarketTick tickRow(ResultSet r,int n)throws SQLException{return new SimulatedMarketTick(uuid(r,"id"),uuid(r,"fund_id"),r.getObject("tick_date",LocalDate.class),r.getInt("change_bps"),r.getBigDecimal("nav_before"),r.getBigDecimal("nav_after"),uuid(r,"fund_nav_id"),instant(r,"created_at"));}private HoldingFeeRule holdingRow(ResultSet r,int n)throws SQLException{return new HoldingFeeRule(uuid(r,"id"),uuid(r,"fund_id"),r.getLong("rule_version"),r.getInt("minimum_holding_days"),r.getBigDecimal("early_fee_rate"),instant(r,"created_at"));}
 private static byte[] digest(String value){try{return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));}catch(Exception e){throw new IllegalStateException(e);}}private static UUID uuid(ResultSet r,String c)throws SQLException{Object v=r.getObject(c);return v instanceof UUID u?u:UUID.fromString(String.valueOf(v));}private static UUID uuid(ResultSet r,int c)throws SQLException{Object v=r.getObject(c);return v instanceof UUID u?u:UUID.fromString(String.valueOf(v));}private static Instant instant(ResultSet r,String c)throws SQLException{Timestamp t=r.getTimestamp(c);return t==null?null:t.toInstant();}private static Timestamp ts(Instant i){return Timestamp.from(i);}private record Nav(UUID id,BigDecimal nav){}
}
